def greedy_build(num_vertices, num_edges):
    current_edges = []
    all_possible_edges = list(itertools.combinations(range(num_vertices), 2))

    for _ in range(num_edges):
        best_edge = None
        min_max_g = float('inf')

        sample_size = 30
        test_edges = random.sample(all_possible_edges, sample_size)

        for edge in test_edges:
            if edge in current_edges:
                continue

            new_edges = current_edges + [edge]
            mg = get_max_g(new_edges, num_vertices)
            if mg < min_max_g:
                min_max_g = mg
                best_edge = edge

        if best_edge:
            current_edges.append(best_edge)
        else:
            remaining = [e for e in all_possible_edges if e not in current_edges]
            current_edges.append(random.choice(remaining))

    return current_edges, get_max_g(current_edges, num_vertices)

