def f_15_n2_8(n2):
    # This is a known problem: find the maximum number of edges in a graph
    # with 15 vertices such that every subgraph of 8 vertices has at most k edges.
    # We want to find the minimum k such that such a graph exists for a given n2.
    # For n=15, k=8, n2=56, we had an average of 14.93, so k=15.
    # A simple upper bound for k is ceil(n2 * (8*7 / (15*14))) = ceil(n2 * 28/105) = ceil(4/15 * n2).
    # Let's check small values of n2 and see if ceil(4/15 * n2) is always enough.
    # For n2=1, k=1. For n2=2, k=1. For n2=3, k=1. For n2=4, k=2.
    # This looks like it should be close to ceil(4/15 * n2).
    return (4 * n2 + 14) // 15

