def solve():
    num_vertices = 15
    num_edges = 56
    subgraph_size = 8

    for _ in range(10):
        adj = [[False]*num_vertices for _ in range(num_vertices)]
        all_possible = list(itertools.combinations(range(num_vertices), 2))
        random.shuffle(all_possible)
        edges = all_possible[:num_edges]
        for u, v in edges:
            adj[u][v] = adj[v][u] = True

        current_max_e, max_combo = count_max_e(adj, num_vertices, subgraph_size)
        print(f"Initial max_e = {current_max_e}")

        if current_max_e <= 15:
