def min_cut_7(edges, n=15):
    min_c = float('inf')
    for I in itertools.combinations(range(n), 7):
        I_set = set(I)
        count = 0
        for u, v in edges:
            if (u in I_set) != (v in I_set):
                count += 1
        if count < min_c:
            min_c = count
    return min_c

